CREATE TOPIC `app/events` (CONSUMER a WITH (important = true, supported_codecs = 'gzip, raw'), CONSUMER b WITH (read_from = Timestamp('2026-01-01T00:00:00Z'), availability_period = Interval('PT2H'))) WITH (min_active_partitions = 2, max_active_partitions = 8, auto_partitioning_strategy = 'scale_up_and_down', auto_partitioning_up_utilization_percent = 70, auto_partitioning_down_utilization_percent = 20, auto_partitioning_stabilization_window = Interval('PT5M'), retention_period = Interval('PT48H'), partition_write_speed_bytes_per_second = 2048, partition_write_burst_bytes = 4096, supported_codecs = 'raw,zstd');